  FINDERS,

  f => agent(
    f.type === "rapid" ? RAPID_PROMPT(f.idx) : DEEP_PROMPT(f.idx),
    { label: f.type + "-" + f.idx, phase: "Find", schema: BUGS_SCHEMA }
