const EVIDENCE_BLOCK =
  "## Incident\\n" + TASK + "\\n\\n" +
  "## Timeline\\n" + gather.timeline + "\\n\\n" +
  "## Scope\\n" + gather.scope + "\\n\\n" +
  "## Evidence\\n" + gather.evidence.map((e, i) => (i + 1) + ". " + e).join("\\n") + "\\n" +
