))
const hyps = hypotheses.map((h, i) => h ? { ...h, angle: ANGLES[i].key } : null).filter(Boolean)
if (hyps.length === 0) return { error: 'No hypotheses generated.', gather }
log(hyps.length + ' hypotheses: ' + hyps.map(h => h.angle).join(', '))

